parameters.jsCode:
// ============================================
// NODO: ValidateWorkoutDuration
// PROPÓSITO: Validar que rutinas diarias caben en tiempo disponible
// ============================================

const userProfile = $('ProcessUserPreferences').item.json;
const dayRequirements = $('Get_Day_Requirements').all().map(r => r.json);
const inputItems = $input.all();
const allWorkouts = inputItems.map((item, idx) => ({ ...item.json, _originalIndex: idx }));

// === CONFIGURACIÓN ===
const WARMUP_BUFFER = 600; // 10 min calentamiento
const TRANSITION_TIME = 30; // 30 seg entre ejercicios

// === HELPERS ===

function parseSessionDuration(durationStr) {
  if (!durationStr) return 70;
  if (durationStr.includes('45')) return 55;
  if (durationStr.includes('60') || durationStr.includes('75')) return 70;
  if (durationStr.includes('90') || durationStr.includes('Mas de 75')) return 85;
  return 70;
}

function parseTempo(tempoStr) {
  if (!tempoStr || typeof tempoStr !== 'string') return 4; // default
  return tempoStr.split('-')
    .map(n => parseInt(n, 10) || 0)
    .reduce((sum, phase) => sum + phase, 0);
}

function calculateExerciseTime(exercise) {
  const sets = parseInt(exercise.sets, 10) || 3;
  const reps = parseInt(exercise.reps, 10) || 10;
  const restSeconds = parseInt(exercise['rest-seconds'] || exercise.rest_seconds, 10) || 60;
  const tempoPerRep = parseTempo(exercise.tempo);

  const workTime = sets * reps * tempoPerRep;
  const restTime = (sets - 1) * restSeconds;

  return workTime + restTime;
}

function calculateDayDuration(exercises) {
  const exerciseTime = exercises.reduce((sum, ex) =>
    sum + calculateExerciseTime(ex), 0
  );
  const transitions = (exercises.length - 1) * TRANSITION_TIME;
  return (exerciseTime + transitions + WARMUP_BUFFER) / 60; // minutos
}

function reduceWorkout(exercises, targetMin) {
  let currentDuration = calculateDayDuration(exercises);
  let iterations = 0;
  const MAX_ITER = 20;

  while (currentDuration > targetMin && iterations < MAX_ITER) {
    const reducible = exercises
      .map((ex, idx) => ({
        idx,
        sets: parseInt(ex.sets, 10),
        min: 2, // mínimo seguro por ejercicio individual
        role: ex.role,
        impact: calculateExerciseTime({...ex, sets: "1"})
      }))
      .filter(r => r.sets > r.min)
      .sort((a, b) => {
        const roleOrder = { isolation: 1, core: 2, compound: 3 };
        const diff = (roleOrder[a.role] || 2) - (roleOrder[b.role] || 2);
        return diff !== 0 ? diff : b.impact - a.impact;
      });

    if (reducible.length === 0) break;

    const target = reducible[0];
    exercises[target.idx].sets = String(target.sets - 1);
    currentDuration = calculateDayDuration(exercises);
    iterations++;
  }

  return {
    exercises,
    duration: currentDuration,
    adjusted: iterations > 0,
    meetsTarget: currentDuration <= targetMin
  };
}

// === PROCESAMIENTO ===

const targetMinutes = parseSessionDuration(userProfile.session_duration_mins);

// Agrupar workouts por semana y día
const grouped = {};
allWorkouts.forEach(w => {
  const key = `W${w.week_number}-${w.day_name}`;
  if (!grouped[key]) grouped[key] = [];
  grouped[key].push(w);
});

// Validar cada día
const processedWorkouts = [];
const validationLog = [];

for (const [key, dayWorkouts] of Object.entries(grouped)) {
  const [week, dayName] = key.split('-');
  const initialDuration = calculateDayDuration(dayWorkouts);

  if (initialDuration > targetMinutes) {
    const result = reduceWorkout(dayWorkouts, targetMinutes);

    validationLog.push({
      week,
      day: dayName,
      initial_min: Math.round(initialDuration),
      final_min: Math.round(result.duration),
      target_min: targetMinutes,
      adjusted: result.adjusted,
      status: result.meetsTarget ? 'OK' : 'OVER_TARGET'
    });

    processedWorkouts.push(...result.exercises);
  } else {
    validationLog.push({
      week,
      day: dayName,
      duration_min: Math.round(initialDuration),
      target_min: targetMinutes,
      status: 'OK'
    });

    processedWorkouts.push(...dayWorkouts);
  }
}

// Log de validación
console.log('=== WORKOUT TIME VALIDATION ===');
console.log(`User: ${userProfile.whatsapp_id}`);
console.log(`Target Session: ${targetMinutes} min`);
console.log('Results:', JSON.stringify(validationLog, null, 2));

// Retornar workouts procesados con pairedItem correcto
return processedWorkouts.map(w => {
  const originalIdx = w._originalIndex;
  delete w._originalIndex; // limpiar el campo temporal

  return {
    json: w,
    pairedItem: originalIdx
  };
});
